-- 회복 정책 확장 2: 개별 국가 모델(스위스·캐나다·스코틀랜드) + 안전소비시설 개념
-- 정의/본문/심화 전부 신규 작성. 현행 사실은 웹 검색 확인(2024~2025).
-- 실행: psql -h localhost -U postgres -d addiction_news -f inject_recovery_policy2.sql
BEGIN;
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('swiss-four-pillars', '스위스 4기둥 모델', 'Swiss Four-Pillar Model', 'policy', '스위스가 1990년대 심각한 마약·HIV 위기 속에서 도입한 마약 정책으로, 예방·치료·피해감소·법집행이라는 네 기둥을 균형 있게 결합한다. 처벌 중심의 금욕 지향이 위기에 대응하지 못하자, 실용적 공중보건 접근으로 전환한 대표 사례이며, 국민투표로 재확인된 정책이다.', '기존 치료에 반응하지 않던 만성 헤로인 사용자에게 의료적으로 통제된 환경에서 약제급 헤로인을 처방하는 헤로인 보조치료(HAT).', '["recovery-policy-global", "harm-reduction", "medication-assisted-treatment", "supervised-consumption", "portugal-model"]'::jsonb, true, false, '[{"h": "무엇인가", "p": "스위스 4기둥 모델은 마약 문제에 대응하는 네 축—예방, 치료, 피해감소, 법집행—을 균형 있게 결합한 국가 정책이다. 어느 하나에 치우치지 않고 네 기둥을 함께 세운다는 점, 그리고 ''마약과의 전쟁''이 아니라 해악을 줄이고 사람을 돕는 것을 목표로 삼는다는 점이 핵심이다."}, {"h": "왜 시작됐나", "p": "1980~90년대 스위스는 공개된 마약 거래 장소(취리히의 ''니들 파크'' 등)와 급증하는 HIV 감염·과용 사망이라는 심각한 위기를 겪었다. 기존의 금욕 지향 처벌 정책이 이를 감당하지 못하자, 지역 차원의 혁신적 공중보건 프로그램(저문턱 메타돈, 주사기 교환, 안전소비시설, 헤로인 처방)에서 출발해 국가 정책으로 발전시켰다."}, {"h": "헤로인을 처방한다고?", "p": "가장 논쟁적이었던 것은 치료에 반응하지 않는 만성 사용자에게 의료적으로 통제된 환경에서 약제급 헤로인을 처방하는 헤로인 보조치료(HAT)였다. ''사용을 조장한다''는 우려와 달리, 불법 헤로인 사용과 관련 범죄·감염·사망이 줄고 사회적 기능(주거·고용)이 개선되는 결과가 보고됐다."}, {"h": "결과와 정착", "p": "수십 년의 정밀한 기록·평가를 통해 과용 사망·HIV 감염·마약 관련 범죄 감소와 치료 접근성 향상이 확인됐고, 공개 마약 거래 장소도 사실상 사라졌다. 이 성과가 여론의 지지를 넓혀, 4기둥 정책은 국민투표로 재확인되며 법제화됐다. 근거를 쌓아 사회적 합의를 이룬 대표 사례다."}]'::jsonb, '[{"h": "HAT의 근거", "p": "헤로인 보조치료는 무작위 대조시험으로 경구 메타돈과 비교되며 그 특수한 가치가 입증됐고, EMCDDA·코크란 리뷰 등이 건강·사회적 기능 개선과 불법 사용·범죄 감소를 확인했다. 다만 엄격한 기준(장기 사용, 기존 치료 실패)에서만 제공되며, 근거에도 불구하고 시행 국가는 소수에 그친다."}, {"h": "성공의 조건", "p": "스위스 사례의 교훈은 네 기둥의 ''통합성''에 있다. 피해감소만도, 처벌만도 아닌 균형, 지역 차원의 실험, 정밀한 평가와 공개 토론, 그리고 광범위한 대중적 지지가 결합해 정착했다. 연방제·합의 민주주의라는 정치 문화가 이 점진적 전환을 가능하게 했다는 분석이 있다."}, {"h": "성공의 역설", "p": "흥미롭게도 정책이 성공해 마약 문제가 눈에 덜 띄게 되자, 지속적 개혁의 동력과 재정 지원 의지가 약해지는 역설이 나타났다. 위기가 잦아든 뒤에도 정책을 유지·발전시키는 것이 또 다른 과제임을 스위스 사례가 보여준다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('canada-scs', '캐나다 안전소비시설', 'Canada''s Supervised Consumption Sites', 'policy', '캐나다가 운영하는 안전소비시설(SCS)로, 사용자가 가져온 약물을 훈련된 전문가의 감독 아래 안전하게 사용하도록 하는 피해감소 시설이다. 2003년 밴쿠버의 Insite가 북미 최초로 문을 열었고, 이후 여러 주로 확대됐으나 최근 일부 주의 축소·폐쇄 움직임 속에 논쟁이 이어진다.', '밴쿠버 Insite에서 사용자가 자신의 약물을 위생적 환경에서 사용하고, 과용 시 즉시 응급 대응을 받으며 치료·주거 서비스로 연결되는 것.', '["supervised-consumption", "harm-reduction", "naloxone", "recovery-policy-global", "scotland-thistle"]'::jsonb, true, false, '[{"h": "무엇인가", "p": "안전소비시설(SCS)은 사용자가 가져온 약물을 훈련된 전문가의 감독 아래 위생적 환경에서 사용하도록 하는 시설이다. 시설이 약물을 제공하지는 않으며, 과용을 즉시 되돌리고 감염을 막으며 치료·사회 서비스로 연결하는 접점 역할을 한다."}, {"h": "어떻게 작동하나", "p": "2003년 밴쿠버 다운타운 이스트사이드에 북미 최초의 시설 Insite가 문을 열었다. 캐나다 형법상 시설 내부에 한해 규제물질법의 예외가 적용되지만, 시설 밖에서 소지는 여전히 불법이다. 사용자는 시설 안에서 안전하게 사용하고, 과용 시 응급 대응을 받으며, 원할 경우 치료·주거·의료로 연결된다."}, {"h": "어떤 효과가 있었나", "p": "연구들은 Insite가 과용 사망과 HIV 감염을 줄이고, 공공장소 사용·주사기 방치를 감소시켰으며, 상당한 의료비를 절감했다고 보고한다. 낙인 없이 취약한 사용자를 서비스로 연결하는 접점이라는 점이 핵심 가치로 꼽힌다."}, {"h": "최근의 논쟁", "p": "효과에 대한 근거에도 불구하고, 최근 온타리오 등 일부 주는 시설 축소·폐쇄로 방향을 틀고 있다. 인근 지역의 무질서·안전 우려와, 시설이 회복보다 유지에 치우친다는 비판이 정치적 후퇴를 불렀다. 피해감소와 회복 중심 접근 사이의 균형 논쟁이 캐나다에서 첨예하게 나타나는 국면이다."}]'::jsonb, '[{"h": "근거와 비용효과", "p": "Insite에 대한 연구는 시설 개소 후 인근의 과용 사망 감소, HIV 감염 예방을 통한 대규모 의료비 절감을 보고했다. 다만 안전공급·비범죄화 정책과 과용 결과의 관계를 다룬 근래 연구들은 결과가 엇갈려, 정책 효과의 해석은 여전히 논쟁적이다."}, {"h": "피해감소 대 회복의 긴장", "p": "캐나다 논쟁의 핵심은 ''피해감소 전문가와 회복 전문가는 다른 학교''라는 지적에 집약된다. 생명을 지키는 것과 회복으로 이끄는 것 중 어디에 자원을 둘지, 둘의 균형을 어떻게 맞출지가 쟁점이다. 어느 한쪽만으로는 부족하다는 것이 양측이 공유하는 문제의식이다."}, {"h": "안전공급 실험", "p": "캐나다는 오염된 불법 약물(펜타닐)로 인한 사망을 막기 위해, 규제된 약물을 처방·제공하는 ''안전공급(safer supply)'' 실험도 진행했다. 그러나 그 효과와 부작용(전용 등)을 둘러싼 근거 논쟁이 이어지며, 피해감소 정책이 마주한 새로운 시험대가 되고 있다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('scotland-thistle', '스코틀랜드 안전소비시설', 'Scotland''s Safer Drug Consumption Facility', 'policy', '스코틀랜드 글래스고에 2025년 1월 문을 연 영국 최초의 안전소비시설 ''The Thistle''로, 유럽 최악 수준의 약물 사망 위기에 대응하기 위한 3년 시범사업이다. 소지를 처벌하는 영국 법의 벽을, 시설 내 소지를 기소하지 않겠다는 검찰총장의 방침으로 우회해 개소했다.', '글래스고 The Thistle에서 오래 주사 사용을 해 온 사람이 감독하에 안전하게 사용하고, 상처 치료·감염 검사·주거·회복 서비스로 연결되는 것.', '["supervised-consumption", "canada-scs", "harm-reduction", "recovery-policy-global"]'::jsonb, true, false, '[{"h": "무엇인가", "p": "The Thistle은 2025년 1월 글래스고에 문을 연 영국 최초의 안전소비시설이다. 사용자가 가져온 약물을 훈련된 보건·사회복지 전문가의 감독 아래 위생적 환경에서 사용하도록 하며, 과용·감염 위험을 줄이고 치료·회복 서비스로 연결하는 것을 목표로 한다."}, {"h": "왜 만들어졌나", "p": "스코틀랜드는 유럽 최악 수준의 약물 관련 사망률을 겪어왔고, 특히 사회적 박탈이 심한 지역에서 사망이 집중됐다. 글래스고는 공공장소 주사 사용과 HIV 집단감염 문제에 대응하기 위해 오래전부터 이 시설을 요구해 왔다."}, {"h": "법의 벽을 어떻게 넘었나", "p": "약물 소지를 처벌하는 영국의 마약오용법이 오랫동안 개소를 막았다. 2023년 스코틀랜드 검찰총장이 ''시설 내 개인 사용 목적 소지는 기소가 공익에 부합하지 않는다''는 방침을 밝히고 2025년 이를 공식화하면서 길이 열렸다. 다만 이 방침은 시설 내부에 한정되며 주변 지역에는 적용되지 않는다."}, {"h": "진행형 실험", "p": "The Thistle은 스코틀랜드 정부가 연간 예산을 지원하는 3년 시범사업으로, 독립 평가가 진행 중이다. 개소 초기 별다른 의료 응급 없이 다수가 이용했고 일부는 이미 주거·회복 서비스로 연결됐다는 보고가 있으나, 인근 주민의 우려와 ''회복 서비스에 대한 투자가 부족하다''는 비판도 함께 제기된다."}]'::jsonb, '[{"h": "''황금 표준'' 서비스 설계", "p": "The Thistle은 트라우마 기반 돌봄 훈련을 받은 다학제 팀(간호·심리·사회복지·의료·피해감소)이 운영하며, 당사자 경험을 반영해 공간을 설계했다. 개인 부스, 사용 후 회복 공간, 상처 치료·감염 검사실을 갖추고, 취약 집단을 판단 없이 서비스로 연결하는 것을 지향한다."}, {"h": "피해감소 대 회복 논쟁", "p": "글래스고에서도 ''피해감소 전문가와 회복 전문가는 다르다''는 긴장이 드러난다. 시설을 ''실패의 인정''으로 보는 회복 중심 진영과, ''넓은 돌봄 체계의 일부''로 보는 진영이 맞서며, 재활 서비스에 대한 투자 균형이 요구된다. 시설 옹호자들도 ''단독 해법이 아니라 더 넓은 돌봄 체계의 일부''임을 강조한다."}, {"h": "평가와 확산의 관건", "p": "이 시범사업의 독립 평가 결과가 영국 내 다른 지역으로의 확산 여부를 좌우할 전망이다. 인근 지역의 범죄·무질서 우려, 시설 밖 정책과의 정합성, 재정 지속성이 관건이며, 근거가 축적되기까지의 정치적 인내가 시험대에 올라 있다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('supervised-consumption', '안전소비시설', 'Supervised Consumption Sites', 'policy', '사용자가 가져온 약물을 훈련된 전문가의 감독 아래 위생적 환경에서 사용하도록 하는 피해감소 시설의 총칭이다. 과용 사망과 감염을 줄이고 취약한 사용자를 치료·사회 서비스로 연결하는 것을 목표로 하며, 전 세계 100곳 이상에서 운영된다.', '공공장소에서 위험하게 주사하던 사람이, 감독형 시설에서 안전하게 사용하고 과용 시 즉시 응급 대응을 받는 것.', '["harm-reduction", "canada-scs", "scotland-thistle", "swiss-four-pillars", "naloxone"]'::jsonb, true, false, '[{"h": "무엇인가", "p": "안전소비시설은 사용자가 가져온 약물을 훈련된 보건 전문가의 감독 아래 위생적 환경에서 사용하도록 하는 시설이다. 과용 방지시설·감독형 주사시설·약물소비실 등 여러 이름으로 불리며, 시설이 약물을 공급하지는 않는다."}, {"h": "무엇을 하나", "p": "과용을 즉시 되돌리고, 깨끗한 장비로 감염(HIV·간염)을 막으며, 안전한 사용법을 안내한다. 무엇보다 기존 서비스에 닿지 않던 취약한 사용자를 판단 없이 만나, 치료·주거·의료로 연결하는 접점이 된다."}, {"h": "왜 논쟁적인가", "p": "''사용을 용인·조장한다''는 도덕적 비판과 인근 지역의 무질서 우려가 반대의 핵심이다. 그러나 근거는 시설이 사용을 늘리지 않으면서 과용 사망·감염을 줄인다고 보고한다. 공공장소 사용이 이미 많은 지역에서 특히 효과적이라는 점도 확인된다."}, {"h": "세계적 확산", "p": "안전소비시설은 유럽·캐나다·호주 등 세계 100곳 이상에서 운영되며, 2025년 영국(글래스고)과 2024년 남미(보고타)로도 확산됐다. 각국의 법·정치 환경에 따라 도입과 후퇴가 엇갈리는, 피해감소 정책의 최전선이다."}]'::jsonb, '[{"h": "근거의 폭과 한계", "p": "체계적 문헌고찰들은 안전소비시설이 과용 사망 감소, 감염 예방, 서비스 연계, 비용 절감에 기여함을 보고한다. 다만 지역 범죄·공공질서에 대한 영향, 그리고 최근 일부 관할의 후퇴 사례는 효과의 맥락 의존성을 보여주며, 근거와 정치적 수용성 사이의 간극이 크다."}, {"h": "모델의 다양성", "p": "시설마다 운영 방식이 다르다. 밴쿠버·시드니처럼 현장에서 과용을 관리하는 곳이 있는가 하면, 일부 국가는 규정상 응급차를 불러야 한다. 주사기 교환·약물 검사·회복 연계를 어디까지 결합하느냐에 따라 시설의 성격과 성과가 달라진다."}, {"h": "회복 체계 안의 위치", "p": "안전소비시설은 ''단독 해법''이 아니라 예방·치료·회복으로 이어지는 넓은 돌봄 체계의 한 부분으로 설계될 때 의미를 갖는다. 생명을 지키는 접점이 이후 치료·회복으로 이어지도록 하는 연계가 관건이며, 이는 회복지향 시스템(ROSC)이 강조하는 연속적 돌봄과 맞닿는다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
COMMIT;
-- 확인:
SELECT id, category, jsonb_array_length(body) b, jsonb_array_length(advanced) a FROM encyclopedia_terms WHERE id IN ('swiss-four-pillars','canada-scs','scotland-thistle','supervised-consumption') ORDER BY id;
